INSERT INTO `contestant_introductions` (`id`, `season_id`, `episode_id`, `contestant_id`, `sort_order`, `intro_text`, `intro_text_notes`) VALUES
(1, 43, 302, 301, 1, 'Ana Begic Tahiri, a person with more surnames than acting achievements!', NULL),
(2, 43, 302, 302, 2, 'He’s a Herzegovinian and a stand-up comedian. Well, there must be at least one Herzegovinian, because there are 6-7 of us on stage... Igor Drljo!', NULL),
(3, 43, 302, 303, 3, 'The activist and politician known as Richard is not here, so instead you will meet Enio Mestrovic!', '\'Richard\' is Enio\'s alter ego.'),
(4, 43, 302, 300, 4, 'She’s pretty, smart, and talented, so it’s not really clear to us what she’s doing here: Lidija Bacic!', NULL),
(5, 43, 302, 299, 5, 'A man who needs no introduction, because no one knows who he is. He’s a stand-up comedian from Split... Ante [mumbles incorrect last name].', NULL),
(6, 43, 303, 302, 1, 'He’s a small man trapped in the body of an even smaller man: Igor Drljo!', NULL),
(7, 43, 303, 301, 2, 'One of the greatest actresses of today... is not here. But Ana Begic Tahiri is with us!', NULL),
(8, 43, 303, 300, 3, 'Showing us just how far the music industry has fallen during Covid: Lidija Bacic!', NULL),
(9, 43, 303, 303, 4, 'A thorn in the side of Zadar politics, and of this show: Enio Mestrovic!', NULL),
(10, 43, 303, 299, 5, 'Split stand-up comedian Ante [mumbles incorrect last name].', NULL),
(11, 43, 304, 300, 1, 'A woman who is apparently allergic to baggy clothes: Lidija Bacic!', NULL),
(12, 43, 304, 302, 2, 'The man who let his beard grow out to look better. See it on the screen and judge for yourself: Igor Drljo!', NULL),
(13, 43, 304, 301, 3, 'Ana Begic Tahiri is with us. By the way, I found out that she married Mr Tahiri - who is from Dubrava - who visited me and drove me around in his car trunk. So she will have the best introduction of all: Ana Begic Tahiri is a beautiful being who is unique in the universe, and we all love her very much. I hope you are satisfied, Mr Tahiri.', 'There is a running joke during this episode of Ivan apologising to Ana\'s husband, whenever he makes a joke at her expense, the implication being that Ana\'s husband is some kind of mafioso who will harm Ivan for treating her poorly.'),
(14, 43, 304, 303, 4, 'A thorn in the side of Zadar politics, and of this show, Enio Mestrovic!', NULL),
(15, 43, 304, 299, 5, 'And also with us is the talented Split stand-up comedian Ante... [mumbles incorrect last name].', NULL),
(16, 43, 305, 300, 1, 'The person who obviously dresses in the children’s department: Lidija Bacic!', NULL),
(17, 43, 305, 303, 2, 'Just one of the twelve people that live in his head… Enio Mestrovic is with us!', NULL),
(18, 43, 305, 301, 3, 'Our most famous and best actress, but you only know her from <em>Bibin Svijet</em>: Ana Begic Tahiri!', '<em>Bibin Svijet</em> [\'Bibin\'s World\'] is Ana\'s break-out sitcom.'),
(19, 43, 305, 302, 4, 'This show has international reach because he is here from the far, far... Herzegovina. Igor Drljo!', 'Herzegovina actually borders Croatia.'),
(20, 43, 305, 299, 5, 'And with us is an already well-known Split stand-up comedian, the talented Ante... Simovic.', NULL),
(21, 43, 306, 302, 1, 'When he’s not a stand-up comedian, he’s helping Santa Claus at the North Pole: Igor Drljo!', NULL),
(22, 43, 306, 300, 2, '39 singles, 23 videos, four studio albums, and she ended up on this show: Lidija Bacic!', NULL),
(23, 43, 306, 301, 3, 'She once described herself as “punctual, fast, and a pain”. We disagree with that; she’s never punctual. Ana Begic Tahiri!', NULL),
(24, 43, 306, 303, 4, 'When he isn’t ruining the budget of the city of Zadar, he’s ruining our ratings: Enio Mestrovic!', NULL),
(25, 43, 306, 299, 5, 'The Split comedian, always smiling and in a good mood: Ante... Stipisic.', NULL),
(26, 43, 307, 300, 1, 'Honestly, we thought she would be embarrassed by the tasks, but then we watched her music video ‘Kaktus’: Lidija Bacic!', NULL),
(27, 43, 307, 301, 2, 'No blemish on her resume, and with a flawless career... until now... Ana Begic Tahiri!', NULL),
(28, 43, 307, 303, 3, 'From the city of lunatics and basketball – he is both – Enio Mestrovic!', NULL),
(29, 43, 307, 302, 4, 'Because he knows someone from RTL, unfortunately... Igor Drljo is here!', 'RTL is the network that Direktor Svemira airs on.'),
(30, 43, 307, 299, 5, 'Always a smiling and wonderful gentleman with a nice smile. Please, a round of applause for the already very well known... Antu! ...Sviric? Is it Sviric?', 'Yes, he even mispronounces Ante\'s first name in this one.'),
(31, 43, 308, 303, 1, 'The more we know him, the more we fear him: Enio Mestrovic!', NULL),
(32, 43, 308, 300, 2, 'Winner of EuroVision, she never was: Lidija Bacic!', NULL),
(33, 43, 308, 302, 3, 'Proof that not everyone on television is attractive and smart: Igor Drljo!', NULL),
(34, 43, 308, 301, 4, 'For ‘The Nutcracker’, the play that was sold out months in advance at her theatre, there are no more tickets. For her own play, of course, there are still plenty: Ana Begic Tahiri!', NULL),
(35, 43, 308, 299, 5, 'Also here with us, a comedian from Split: Ante... Spipipic!', NULL),
(36, 43, 309, 301, 1, 'Still smiling, and she hasn’t left this show yet: Ana Begic Tahiri!', NULL),
(37, 43, 309, 303, 2, 'We’ll soon find out if he’s taken his pills: Enio Mestrovic!', NULL),
(38, 43, 309, 300, 3, 'Whatever they’re feeding you in Split, please continue: Lidija Bacic!', NULL),
(39, 43, 309, 302, 4, 'Whatever they’re feeding you in Herzegovina, please make them stop: Igor Drljo!', NULL),
(40, 43, 309, 299, 5, 'Stand-up comedian from Split: Ante... Karadjordjevic.', NULL),
(41, 43, 310, 301, 1, 'We called her to calm the situation, but she aggravated it: Ana Begic Tahiri!', NULL),
(42, 43, 310, 303, 2, 'Let us now greet one of the 12 people in his head: Enio Mestrovic!', NULL),
(43, 43, 310, 300, 3, 'She sings like a sparrow, but is stubborn like... a... kitten. Lidija Bacic!', 'In the original Croatian, \'Bacic\' and the word for \'sparrow\' rhyme, so Ivan was searching for another word that rhymed. Ana suggested \'kitten\', which also rhymed, so that\'s what he went with.'),
(44, 43, 310, 302, 4, 'From the capital of Herzegovina... Zagreb... Igor Drljo is here!', 'Zagreb is actually the Croatian capital.'),
(45, 43, 310, 299, 5, 'The Split comedian is also with us: Ante Popovic Volaric!', NULL),
(46, 43, 311, 300, 1, 'The talented and beautiful Lidija Bacic!', NULL),
(47, 43, 311, 301, 2, 'Our great actress with a great laugh: Ana Begic Tahiri!', NULL),
(48, 43, 311, 303, 3, 'He’s a great man and a big man: Enio Mestrovic!', NULL),
(49, 43, 311, 302, 4, 'A great entertainer and a great man: Igor Drljo!', NULL),
(50, 43, 311, 299, 5, 'A stand-up comedian from Split: Ante Travizi!', 'As Ivan has introduced Ante with incorrect names for the previous nine episodes, the fact that he finally introduces him correctly causes the rest of the contestants to cheer loudly.'),
(51, 1, 1, 56, 1, 'First: he\'s wearing a suit because he\'s both professional, and from a different generation to the others. It\'s the very smart Frank Skinner.', NULL),
(52, 1, 1, 69, 2, 'Secondly, a man who\'s chosen not to wear a suit, and who clearly needs a haircut: Josh Widdicombe.', NULL),
(53, 1, 1, 15, 3, 'Next up, a woman I once genuinely witnessed calling for her mum because she\'d seen a mouse: Roisin Conaty.', NULL),
(54, 1, 1, 48, 4, 'A man who has quickly gained a reputation in comedy for being livid all the time: Romesh Ranganathan.', NULL),
(55, 1, 1, 34, 5, 'Finally, a future poet laureate, if some massive poet disaster happens: Tim Key!', NULL),
(56, 1, 2, 56, 1, 'He\'s one in a million, as he\'s from Birmingham, which has a population of one million. It\'s Frank Skinner.', NULL),
(57, 1, 2, 69, 2, 'Secondly, a man whose hair and voice I still find surprising: Josh Widdicombe.', NULL),
(58, 1, 2, 15, 3, 'She once dropped by my flat with two family packs of meatballs, one of which she ate by herself: Roisin Conaty.', NULL),
(59, 1, 2, 48, 4, 'A man who is as angry as his beard is thick: Romesh Ranganathan.', NULL),
(60, 1, 2, 34, 5, 'And finally, he\'s been in Hollywood films, but when I showed pictures of all of these people to my mother, he was the one she didn\'t know. It\'s Tim Key!', NULL),
(61, 1, 3, 56, 1, 'He\'s recently been awarded an OBE, we presume, because this is gonna be repeated, realistically: Mr Frank Skinner!', NULL),
(62, 1, 3, 69, 2, 'He\'s got rosy cheeks, curly hair, and a very successful career. It\'s Josh Widdicombe.', NULL),
(63, 1, 3, 15, 3, 'She has genuinely over 40,000 unread emails in her inbox, because she is bad at certain aspects of life. It\'s Roisin Conaty.', NULL),
(64, 1, 3, 48, 4, 'He used to be happy, but since we\'ve been filming this show, he\'s not any more. It\'s Romesh Ranganathan.', NULL),
(65, 1, 3, 34, 5, 'He gets asked to do a lot of voiceover work, but I think his face is fine. It\'s Tim Key.', NULL),
(66, 1, 4, 56, 1, 'First up, a man who is technically not yet a pensioner: the legend that is Frank Skinner!', NULL),
(67, 1, 4, 69, 2, 'Next, a man who still gets ID-ed when he buys vodka and knives: it\'s Josh Widdicombe.', NULL),
(68, 1, 4, 15, 3, 'Once, when she was drunk, she offered me a pasta meal which she was going to put every conceivable meat into: it\'s Roisin Conaty.', NULL),
(69, 1, 4, 48, 4, 'He\'s a father, a son, and a very angry man: Romesh Ranganathan.', NULL),
(70, 1, 4, 34, 5, 'Finally, a man who\'s sort of quite handsome, but also sort of not: it\'s Tim Key!', NULL),
(71, 1, 5, 56, 1, 'He is a national treasure, by which I mean he\'s older than the others: it\'s Frank Skinner!', NULL),
(72, 1, 5, 69, 2, 'He sounds a lot like Zippy from \'Rainbow\': it\'s Josh Widdicombe.', NULL),
(73, 1, 5, 15, 3, 'I genuinely once returned to my flat to find her in my bed, eating biscuits and watching a documentary on Colditz: it\'s Roisin Conaty.', NULL),
(74, 1, 5, 48, 4, 'He is the least experienced but the most constantly angry of the contestants: it\'s Romesh Ranganathan.', NULL),
(75, 1, 5, 34, 5, 'Sort of a poet, sort of a comedian, sort of a hairstyle: Tim Key!', NULL),
(76, 1, 6, 56, 1, 'He\'s looked exactly the same for nearly 60 years... I\'ve seen baby pictures. It\'s weird. It\'s the legend that is Mr Frank Skinner!', NULL),
(77, 1, 6, 69, 2, 'When he reached the age of 12, he thought, \'Yep, I\'m sticking with this.\' It\'s Josh Widdicombe!', NULL),
(78, 1, 6, 15, 3, 'After a party at my house, I found this comedian asleep on my sofa with 14 penises drawn on her face: Roisin Conaty!', NULL),
(79, 1, 6, 48, 4, 'Quite simply a lovely, kind man. Probably my favourite. Really the loveliest of all the contestants: Mr Romesh Ranganathan.', NULL),
(80, 1, 6, 34, 5, 'Finally, a man who\'s earned a great deal of respect in the comedy industry, but often lets himself down in social situations: Mr Tim Key!', NULL),
(81, 21, 149, 143, 1, 'If you were to make the perfect boy band, you probably wouldn’t include Christian Fuhlendorff.', NULL),
(82, 21, 149, 144, 2, 'She’s a role model for every young girl who dreams of becoming the next Lina Rafn: the first Lina Rafn.', NULL),
(83, 21, 149, 145, 3, 'He\'s an old sailor, an experienced comedian, 90 years of mind, but still looks just like a happy, young lad: Nikolaj Stokholm.', NULL),
(84, 21, 149, 146, 4, 'The man who has more costume changes than the others combined, Ruben Søltoft.', NULL),
(85, 21, 149, 147, 5, 'Known not only from Midsommer, but also from all other times of the year: Julie Ølgaard.', '<em>Midsommer</em> [\'Midsummer\'] was the 2003 psychological horror film in which she landed her breakthrough role.'),
(86, 21, 150, 143, 1, 'The man who lives in Bendtner\'s childhood home: Christian Fuhlendorff', 'Nicklas Bendtner is a former Danish footballer.'),
(87, 21, 150, 144, 2, 'It\'s about 1,000km from Paris to Berlin, but only about 7km to her front door, Lina Rafn.', '<em>From Paris to Berlin</em> was the name of the third studio album by Lina\'s dance-pop duo, Infernal, and also the name of one of the singles released from that album.'),
(88, 21, 150, 145, 3, 'Two things always amaze me about this gentleman: his appearance, and his voice. Nikolaj Stokholm.', NULL),
(89, 21, 150, 146, 4, 'A man who’s as funny as his hair is tall: Ruben Søltoft.', NULL),
(90, 21, 150, 147, 5, 'Aren’t we all just extras in her life? Julie Ølgaard.', NULL),
(91, 21, 151, 143, 1, 'If life were an orienteering race, he wouldn’t hesitate to use Google Maps: Christian Fuhlendorff.', NULL),
(92, 21, 151, 144, 2, 'The woman who looks like a million, no matter whether she holds a microphone or two tennis rackets: Lina Rafn.', 'This appears to be a reference to her attempt at the \'<a href=\"/task.php?id=571\">Keep the basketball on the treadmill</a>\' task, from the previous episode.'),
(93, 21, 151, 145, 3, 'If it sounds like your father, then it\'s probably Nikolaj \'Stick-daddy\' Stokholm.', 'Nikolaj\'s nickname is \'Stokkefar\' [\'Stick-daddy\'].'),
(94, 21, 151, 146, 4, 'A thousand solutions under a thousand curls: Ruben Søltoft.', NULL),
(95, 21, 151, 147, 5, 'And finally, the woman who proves blondes\' reputations. No, there was no more to that sentence. Julie Ølgaard.', NULL),
(96, 21, 152, 143, 1, 'The fastest way to the docks is Christian Fuhlenheim.', 'This variation on Christian Fuhlendorff\'s last name may be some kind of pun?'),
(97, 21, 152, 144, 2, 'Success like your grandmother used to make it: Lina Rafn.', NULL),
(98, 21, 152, 145, 3, 'How do you describe Nikolaj Stokholm at all?', NULL),
(99, 21, 152, 146, 4, 'A Gummy Bear in human clothing: Ruben Søltoft.', NULL),
(100, 21, 152, 147, 5, 'And the raisin in Mark\'s all-too-willing sausage end: Julie Ølgaard.', ' Old Danish sausage recipes used to call for putting raisins at the end, and the phrase \'Rosinen i pølseende\' [\'The raisin in the sausage end\'] is now used to refer to unexpected surprises, similar to the English phrase, \'The cherry on top\'.'),
(101, 31, 201, 131, 1, 'A woman who\'s in with a shot if I ever refresh K3: the amazing Frieda Van Wijck!', 'K3 was a Belgian pop group consisting of three women, with the line-up changing over the years. Gert founded the group, and is rumoured to have dated two of its members.'),
(102, 31, 201, 128, 2, 'A man who\'s funnier than <em>Bumba</em>, but Bumba speaks better Dutch than he does: the great Sven de Ridder!', 'Bumba is the titular clown character from a Flemish television programme for toddlers, produced by Gert\'s production company, Studio 100.'),
(103, 31, 201, 129, 3, 'A young fawn who\'s as hoppity as <em>Wizzy & Woppy</em>, <em>Maya the Bee</em>, and my entire village of gnomes: the ravishing Olga Leyers!', '<em>Wizzy & Woppy</em>, <em>Maya the Bee</em>, and <em>Kabouter Plop</em> [\'Plop the Gnome\'] are all children\'s TV programmes that were produced by Gert\'s production company, Studio 100.'),
(104, 31, 201, 130, 4, 'The <em>Mega Toby</em> of the art of imitation, and I do so admire him. Earlier he showed off his Guga Baul imitation, and it was so good! It\'s Guga Baùl!', '<em>Mega Toby</em> was a kid\'s TV movie produced by Gert\'s production company, Studio 100.'),
(105, 31, 201, 126, 5, 'A comedian who\'s so Moroccan that he brought his own tajine with him, as well as his thirty siblings: Kamal Kharmach!', NULL),
(106, 31, 202, 131, 1, 'A woman with so much experience that even by bleaching her hair blonde she\'s unable to hide it: Frieda van Wijck!', NULL),
(107, 31, 202, 128, 2, 'So adorable that even I want to hug him occasionally: Sven de Ridder!', NULL),
(108, 31, 202, 129, 3, 'A woman who was born with a silver showbiz spoon in her mouth, which they only managed to remove last year: Olga Leyers!', 'Olga is the youngest daughter of the Belgian musician and television producer Jan Anna August Leyers and the actor Anne Meunier, and all of her sisters are also actors, musicians, or presenters.'),
(109, 31, 202, 130, 4, 'A man of many talents, but he does have to borrow them from others: Guga Baùl!', NULL),
(110, 31, 202, 125, 5, 'He\'s my favorite Coppens... right after Mathias, Dieter, Raf, Rik, and Pico Coppens. The one and only Staf Coppens!', 'Mathias Coppens is a Belgian TV presenter, actor and director, and also Staf\'s brother. Dieter Coppens is a Flemish TV producer, and also a cousin of Staf and Mathias. Raf Coppens is a Flemish cabaret artist and comedian. Rik Coppens was a Belgian footballer. Pico Coppens is a character from the comedy TV series <em>FC De Kampioenen</em>.'),
(111, 31, 203, 131, 1, 'The former leading lady of public television, but now she has to take this job at this commercial TV station. We all have to adapt to make ends meet... Well, maybe not all of us. It\'s the inimitable Frieda van Wijck!', NULL),
(112, 31, 203, 128, 2, 'Our second guest can be found in a lot of different places, but mostly in jumble sales: Sven de Ridder!', NULL),
(113, 31, 203, 129, 3, 'A very loud adolescent who has to keep her hormones under control tonight. Meet Olga Leyers, the hippest teenager in town.', NULL),
(114, 31, 203, 130, 4, 'Our fourth guest has been called the Tom Waes of the second-hand store: Guga Baùl.', NULL),
(115, 31, 203, 127, 5, 'Sometimes called Tom Waes: the one and only Tom Waes.', NULL),
(116, 31, 204, 131, 1, 'A woman who\'s reached such a blessed age that the word \'ribbed\' doesn\'t remind her of contraceptives, but of knitwear: Frieda van Wijck!', NULL),
(117, 31, 204, 128, 2, 'A man who, if he lived in the Middle Ages, wouldn\'t have been <em>at</em>, but <em>under</em> the round table: the noble Sven de Ridder!', NULL),
(118, 31, 204, 129, 3, 'A woman who was Jan Leyers\' fourth go at making a son: Olga Leyers!', 'Olga is the youngest of four daughters of the Belgian musician and TV producer Jan Anna August Leyers and the actor Anne Meunier.'),
(119, 31, 204, 130, 4, 'Nearly everything a woman could want, as well as nearly everything a man would like to be. Which almost makes him what I\'ve already become. The great Guga Baùl!', NULL),
(120, 31, 204, 132, 5, 'A woman who dominated the \'Most Beautiful Woman of Flanders\' list for years, and still easily ranks in the top three this evening: the ravishing Veronique De Kock!', 'Veronique was a model and beauty pageant contestant in her youth, winning the titles of \'Miss Flanders\' in 1994, and \'Miss Belgium\' in 1995.'),
(121, 31, 205, 131, 1, 'A woman whose years of wisdom are so far along that she thinks this is <em>De Laatste Show</em>: Frieda van Wijck!', 'Frieda hosted the late night talk show <em>De Laatste Show</em> [\'The Last Show\'] between 2006 and 2009.'),
(122, 31, 205, 128, 2, 'A man who dreams of one day having a part in a Hollywood movie. After tonight, he\'ll have to wave that dream goodbye: Sven de Ridder!', NULL),
(123, 31, 205, 129, 3, 'Our group\'s baby. She\'s so young, I had to ask her via Tinder to be here tonight: Olga Leyers!', NULL),
(124, 31, 205, 130, 4, 'On chair 4, a man who loves doing impressions of me, but who absolutely sucks at it. He\'s here to discover in person that the original is much better: Guga Baùl!', NULL),
(125, 31, 205, 133, 5, 'Our rotating guest tonight is a 42-year-old man trapped in the body of a 12-year-old gymnast: the one and only Dimitri Leue!', NULL),
(126, 31, 206, 131, 1, 'The first always reminds me of my dearly departed grandfather. He used to say \"Gert, there are two kinds of people. There are smart people, and there are stupid people.\" Tonight she\'s the only one in that first category: Frieda van Wijck!', NULL),
(127, 31, 206, 128, 2, 'A man from the second category: Sven de Ridder!', NULL),
(128, 31, 206, 129, 3, 'On the third chair is a stunningly beautiful girl. I do have to warn the teenage boys watching - don\'t bring her home: Olga Leyers!', NULL),
(129, 31, 206, 130, 4, 'And the fourth is the wet dream of all the women in Flanders - or rather, most of them, because I still have a lock on the elderly demographic: Guga Baúl!', NULL),
(130, 31, 206, 134, 5, 'And finally, our rotating guest for tonight - a man who reaches the same staggering heights I do, but only when it comes to body length: the one and only Rob Vanoudenhoven!', NULL),
(131, 31, 207, 131, 1, 'The first is a woman who just now asked me to not go on too long, because she\'s still got to do the ironing at home: the legendary Frieda van Wijck!', NULL),
(132, 31, 207, 128, 2, 'The second is a man who always tells such exciting stories that they put him at the kids table at family gatherings: the great Sven de Ridder!', NULL),
(133, 31, 207, 129, 3, 'The third is a beautiful girl who is young enough that I could have been her father. But in that case, she wouldn\'t have just been beautiful, but smart and rich as well. The ravishing Olga Leyers!', NULL),
(134, 31, 207, 130, 4, 'And the fourth is a highly competetive man. Every year he covers his entire car with stickers from the Red Cross, because he even wants to be the best at charity: Guga Baúl!', NULL),
(135, 31, 207, 135, 5, 'And, finally, our rotating guest this evening. He\'s a celebrated actor, a cool DJ, a sensitive poet, a renowned painter, and a chav from Antwerp: Axel Daeseleire!', NULL),
(136, 31, 208, 131, 1, 'The first is an absolute woman of class: she can speak 5 languages, had a storied career in journalism, and she\'s seen nearly the entire world. And she\'s here tonight, on the VTM: Frieda van Wijck!', 'VTM is the commercial Flemish TV channel on which Het Grootste Licht was broadcast.'),
(137, 31, 208, 128, 2, 'The second is a man in the best shape of his life. Which is mainly because he recently had to run away a lot from Pokémon-trainers: Sven de Ridder!', NULL),
(138, 31, 208, 129, 3, 'Her boisterously sexy laughter instantly lights a fire in the hearts of men, because it instinctively makes them leap into the nearest fire: the beautiful Olga Leyers!', NULL),
(139, 31, 208, 130, 4, 'The fourth\'s actual name is Laurent Bailleu and, because that name wasn\'t ridiculous enough already, he goes by: Guga Baúl!', 'This is true; his full name is Laurent Gaëtan Bailleul.'),
(140, 31, 208, 136, 5, 'And finally, our rotating guest for the evening. Some actors are often considered slightly mad, but in this case we can be sure: the one and only Stefaan Degand!', NULL),
(141, 44, 344, 329, 1, 'She\'s a Leo, and her biggest dream is to have a natural childbirth. She already tried a childbirth with fruit pieces and a strawberry-flavoured childbirth, but it\'s not quite the same thing. She wants a natural childbirth: Inês Aires Pereira!', NULL),
(142, 44, 344, 328, 2, 'He\'s a Gemini, and his greatest dream is to someday open a school where he can help develop very specific skills in the youth. Who knows? Maybe one day Nuno Markl could enrol to improve his unique talent of imitating orcas. Ladies and gentlemen: Gilmário Vemba!', NULL),
(143, 44, 344, 330, 3, 'A Sagittarius, this woman has been chasing her dream for two years now. No, she doesn\'t want Oscars. No, she doesn\'t want wealth. She just wants to sleep. #LetJessySleep. Jessica Athayde!', NULL),
(144, 44, 344, 327, 4, 'An Aquarius, his dream is to one day make his own versions of famous musicals. Here on Taskmaster, we can hardly wait to attend such classics as “The Sound of Toysic”, “The Phantom of the Toypera” and, of course, my favourite, “Toymma Mia!”. It\'s Toy!', NULL),
(145, 44, 344, 347, 5, 'He\'s a Pisces, and he\'s loved by the Portuguese, and I love him. In fact, I love him so much that, if I wasn\'t married, and he invited me to dinner, and we hit it off... well, I wouldn\'t make any promises. It\'s Fernando Mendes!', NULL),
(146, 44, 345, 329, 1, 'A very talented woman who said that, even today, when she auditions for a role, she sweats from the palms, and also from her upper lip. I now understand how, in the audition for Taskmaster, she gave a moustache to her competitors. It\'s Inês Aires Pereira!', 'The phrase \'dar um bigode\' [\'give a moustache\'] in Portuguese is an idiom meaning \'easily beat the competition\'.'),
(147, 44, 345, 328, 2, 'A very talented man who, at the age of five, accidentally drank petrol. On the bright side, he\'s now a very healthy lad. The downside is that the petrol would now be worth 3,500 euro. It\'s Gilmário Vemba!', NULL),
(148, 44, 345, 330, 3, 'A very talented woman who says that one of the most relaxing things is taking a long bath at the end of the day. Of course, after having become a mother, a \'long bath\' is a 37-second shower, interrupted abruptly by her kid, who wants to poo. It\'s Jessica Athayde!', NULL),
(149, 44, 345, 327, 4, 'A talented man with a lot of history: started smoking at 9; quit by 13; got married at 17; and retired at 21. Which means his entire music career was due to the New Opportunities education programme. It\'s Toy!', 'Novas Opportunidades [\'New Opportunities\'] was the name of a Portuguese government education initiative, in the early 2010s, which allowed people who had completed their education under an older system, or had dropped out of school early, to have their old diplomas updated and officially recognised as a high school degree. The initiative was widely mocked as an attempt by the government to artificially raise the population\'s academic levels, so it wouldn\'t look as bad compared to other EU countries.'),
(150, 44, 345, 348, 5, 'A man who once toured the country with a group of 6 musicians, on stage, and now tours with his only his voice and a guitar. I asked if that was an homage to his Brazilian influences, to which he replied, “No, no, I was just tired of splitting the cash with 6 apes.” It\'s António Zambujo!', NULL),
(151, 44, 346, 329, 1, 'Born in 1989, which means that when the Berlin Wall fell, it probably woke her up. It\'s Inês Aires Pereira!', NULL),
(152, 44, 346, 328, 2, 'Born in 1985 in Luanda - not just the capital of Angola, but also a café in Lisbon which, according to their website, \'has good angler fish and fascinating pastries\'. It\'s Gilmário Vemba!', NULL),
(153, 44, 346, 330, 3, 'Also born in 1985, which likely also means that she was conceived to the sound of Baltimora\'s <em>Tarzan Boy</em>. It\'s Jessica Athayde!', '<em>Tarzan Boy</em> was the debut single by the Italian music act Baltimora, and featured a melodic refrain which imitated the signature cry of the movie character Tarzan.'),
(154, 44, 346, 327, 4, 'Born in 1963, he started his career at only five years old, hence his nickname of \'Setúbal\'s Mozart\'. It\'s Wolfgang Amadeus Toy!', 'Toy was born in the Portuguese city of Setúbal.'),
(155, 44, 346, 352, 5, 'Born in 1966 and, in her career, she\'s played John Ford, Frederico Garcia Lorca, Eric-Emmanuel Schmitt, and let us not forget the dog Inspector Max. It\'s Rita Salema!', '<em>Inspetor Max</em> (formerly <em>Inspector Max</em>) is a long-running Portuguese television series in which a police duo fight crime with the help of a dog named Max. Rita actually played two separate human roles in the series, over the years, and not the dog itself!'),
(156, 44, 347, 329, 1, 'She\'s too pregnant to participate in this carousel, risking her unborn child someday asking: “Why, mother? Why?” It\'s Inês Aires Pereira!', NULL),
(157, 44, 347, 328, 2, 'He\'s a superstar in Angola, and his first name is what Luigi says to Mario when he sees the Expo \'98 mascot. It\'s Gil-Mario Vemba!', 'Expo \'98 (1998 Lisbon World Exposition) was a World\'s Fair, held in Lisbon, Portugal, in 1998. The Expo\'s mascot was named Gil, after the Portuguese navigator Gil Eanes.'),
(158, 44, 347, 330, 3, 'Our next contestant started on TVI, has done projects at SIC, and now she\'s on RTP. She may be missing the times she was at SIC and TVI, poor thing. It\'s Jessica Athayde!', 'TVI (Televisão Independente), SIC (Sociedade Independente de Comunicação), and RTP (Rádio e Televisão de Portugal) are all Portuguese TV channel networks.'),
(159, 44, 347, 327, 4, 'Here on Taskmaster, we have our own living legend. But, judging by some of his performances, the question is: “Alive, yes, but until when?” It\'s Toy!', NULL),
(160, 44, 347, 349, 5, 'He used to belong to an academic orchestra which played with toilet flushes and TV cables a few years ago. I\'m assuming nowadays they\'d need to update some of their instruments. Maybe instead of playing cable, he\'d play fibre? Ladies and gentlemen: Pedro Tochas!', 'Pedro was a member of the Orxestra Pitagórica [\'Pythagorean Orchestra\'], which combined traditional instruments with objects such as toilets, traffic signs, cisterns, pitchers, and umbrellas with bells, in some of its later performances of well-known Portuguese songs.'),
(161, 44, 348, 329, 1, 'An actress who, years ago, went to Australia on a 16,000km journey. 16,000km! Curiously, that is also the distance she can be heard screaming “MAAAAAAAAARKL!” It\'s Inês Aires Pereira!', NULL),
(162, 44, 348, 328, 2, 'A comedian who comes up with many jokes on the toilet - a place where, according to him, there is only himself and God. God reacted by saying, “For the love of Me, there are things that I would prefer not to see!” It\'s Gilmário Vemba!', NULL),
(163, 44, 348, 330, 3, 'A wonderful actress who recently gave an interview entitled “I would gladly do this show until the end of the year”. I read the interview and realised: she likes what she does, she likes new things, and she was not talking about Taskmaster. It\'s Jessica Athayde!', NULL),
(164, 44, 348, 327, 4, 'One of the greatest singers in Portugal, who says he loves his audience, which ranges from 2 to 92 years old. Bad news for Mrs Elisabete Silva from Vila Real, who turned 93 yesterday. Congratulations! But, as of yesterday, he doesn\'t give a damn about you. A round of applause for Toy!', NULL),
(165, 44, 348, 366, 5, 'He\'s an actor and has confessed that he is impulsive when driving, which he later regrets. Actually, backstage he said he would like to take this opportunity to apologise to the 347 people and their respective mothers that he insulted on his way here today. It\'s Manuel Marques!', NULL),
(166, 44, 349, 329, 1, 'A beautiful actress. One of the biggest sorrows of her life was when she was not cast for the series <em>Inspector Max</em>. Because of that, German Shepherds dropped two positions in her favourite dog breed ranking, behind the Pinscher and the Chinese Crested Dog. It\'s Inês Aires Pereira!', '<em>Inspetor Max</em> (formerly <em>Inspector Max</em>) is a long-running Portuguese television series in which a police duo fight crime with the help of a dog named Max.'),
(167, 44, 349, 328, 2, 'A professional comedian. On a personal level, he is married and a father of four children. Regarding marriage, he says the part about \'until death do us part\' should be revised because, in his words, \"people nowadays live a long time\". It\'s Gilmário Vemba!', NULL),
(168, 44, 349, 330, 3, 'One more actress, one of the best in the country. When asked about her favourite place, she elected Bali. By the way, we have to hurry, because she\'s catching the 11:45 bus from Campo Grande to Indonesia. It\'s Jessica Athayde!', NULL),
(169, 44, 349, 327, 4, 'He\'s a singer, and says that: when one is young, one talks about women; when middle-aged, one talks about restaurants; and when old, about medical prescriptions. So, in a few years, we\'ll get songs from him like “Stupidly Constipated” and my favourite, “I\'m gonna buy, I\'m gonna take anxiety pills to sleep, all night long.” It\'s Toy!', 'One of Toy\'s albums - and a single from that album - was titled <em>Estupidamente Apaixonado</em> [Stupidly in Love]. One of his most famous songs is <em>Coração não tem idade (Vou Beijar)</em> [Heart has no age (I\'m going to kiss)], also known as <em>Toda a Noite</em> [All night], which has the lyrics \"Vou beijar, vou dançar / Vou hum hum até me cansar / Toda a noite, toda a noite\", which translate to \"I\'m gonna kiss, I\'m gonna dance / I\'m gonna hmm hmm until I\'m exhausted / All night, all night\".'),
(170, 44, 349, 350, 5, 'An actress who started as a ballet dancer. Once, during a show in a room with lots of humidity, her colleagues on stage all began to fall down. She laughed so hard that she peed down her legs. Legend has it that it was the first time the swans had an actual lake. It\'s Carla Andrino!', NULL),
(171, 44, 350, 329, 1, 'She\'s an actress who moved out of her parents\' home in Porto when she started working on TV, at the age of 18. She says she didn\'t like it. Obviously she didn\'t like it - she wasn\'t on Taskmaster. It\'s Inês Aires Pereira!', NULL),
(172, 44, 350, 328, 2, 'A comedian who is married and has four children, who says he doesn\'t go a single day without kissing. Considering the time we spend here together on Taskmaster, I have to tell him: when the need is strong, Markl is always available. It\'s Gilmário Vemba!', NULL),
(173, 44, 350, 330, 3, 'An actress who\'s been on the cover of <em>GQ Magazine</em>, the cover of <em>Vogue</em>, and the cover of <em>Cosmopolitan</em>. That\'s nothing! I\'ve been on the cover of <em>VisãoJunior</em>, of Saúda, by the Portuguese Pharmacies, and I\'m on some highways with a plush horse on my back. It\'s Jessica Athayde!', '<em>VisãoJunior</em> appears to be the youth edition of the weekly Portuguese news magazine <em>Visão</em>. Saúda is the name of a loyalty programme run by the Portuguese Pharmacies brand. Presumably Vasco appeared in some marketing for this programme at some point? No idea what he\'s referencing with the bit about a plush horse on his back...'),
(174, 44, 350, 327, 4, 'He\'s a singer who released his first single in 1985, and says he hasn\'t been robbing banks, nor the people, all these years. However, he is a thief, because for years, he\'s been stealing our hearts. It\'s Toy!', NULL),
(175, 44, 350, 353, 5, 'An actor who played an assassin on <em>Pôr do Sol</em>. He says his son Francisco cried when he saw him in that role. Francisco, don\'t worry. It\'s possible that your father will be the one crying tonight. It\'s Jorge Mourato!', 'Jorge played the character Coronel [Colonel] Facínora on the Portuguese comedy-drama show <em>Pôr do Sol</em> [\'Sunset\'].'),
(176, 44, 351, 329, 1, 'An actress who has so many characters within her that a boyfriend once said, “You\'re amazing and super talented, but can I stay a little with Ines?” The result: the boy went back to his life, and we got her instead. It\'s Inês Aires Pereira!', NULL),
(177, 44, 351, 328, 2, 'A comedian born and raised in Angola, who survived, according to himself: being run over, being poisoned, alcohol intoxication, and shootings. Do you still think Taskmaster is hard? This man\'s here on holiday! It\'s Gilmário Vemba!', NULL),
(178, 44, 351, 330, 3, 'An actress who says she\'ll never forget a hotel in the Bukit region that has a saltwater swimming pool. If you have never tried it, try using the bowl of water in which you\'ve soaked your cod. It might have the same effect. It\'s Jessica Athayde!', NULL),
(179, 44, 351, 327, 4, 'One of our greatest singers. Recently, Monica Sintra asked him a question: “If you were on a deserted island and you could only have one of the following, which one would you pick? Wine, music, or... <em>mm-mmmh</em>” You just have to look at his face to realise that wine and music never stood a chance. It\'s Toy!', 'Mónica Sintra is a Portuguese singer.'),
(180, 44, 351, 351, 5, 'An actress who says she likes a certain level of discomfort. In her own words: “If there\'s something I\'m not skilled at, that\'s what I want to do the most.” Congratulations, you\'re on the right show! It\'s Inês Castel-Branco!', NULL),
(181, 58, 422, 404, 1, 'The fast-talking radio personality, Linnéa Wikblad.', NULL),
(182, 58, 422, 403, 2, 'The ingenious joker, Henrik Nyblom.', NULL),
(183, 58, 422, 405, 3, 'The wonderful entertainer, Nikki Amini.', NULL),
(184, 58, 422, 79, 4, 'The energetic entertainer, Marko Lehtosalo.', NULL),
(185, 58, 422, 409, 5, 'Every week we have a guest. Tonight, it\'s the wisecracking Vasa runner, Måns Möller.', 'Vasaloppet (\'the Vasa-race\') is an annual long distance cross-country ski race held in Sweden on the first Sunday of March. The 90 km course starts in the village of Berga, and ends in the town of Mora. It is the oldest cross-country ski race in the world, and the one with the highest number of participants.'),
(186, 58, 423, 404, 1, 'The funny midfield lock, Linnéa Wikblad!', NULL),
(187, 58, 423, 403, 2, 'The broke ball boy, Henrik Nyblom!', NULL),
(188, 58, 423, 405, 3, 'The fierce shooting queen, Nikki Amini!', NULL),
(189, 58, 423, 79, 4, 'The powerful goal machine, Marko Lehtosalo!', NULL),
(190, 58, 423, 413, 5, 'Tonight we are joined by the distinguished national team captain, Janne Andersson!', 'Janne manages the Swedish national football team.'),
(191, 58, 424, 404, 1, 'The famous radio face, Linnéa Wikblad.', NULL),
(192, 58, 424, 403, 2, 'The beard where everything can get stuck, Henrik Nyblom.', NULL),
