(446, 104, 738, 648, 1, 'Feel no sadness for me: Gina Dirawi.', '<em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/K%C3%A4nn_ingen_sorg_f%C3%B6r_mig_G%C3%B6teborg_(s%C3%A5ng)\">Känn ingen sorg för mig Göteborg</a></em> (‘Feel no sadness for me Gothenburg’) is a song by the Swedish musician Håkan Hellström, from his <a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/K%C3%A4nn_ingen_sorg_f%C3%B6r_mig_G%C3%B6teborg\">album of the same name</a>.'),
(447, 104, 738, 647, 2, 'Your time will come: Alfred Svensson.', '<em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/Din_tid_kommer\">Din tid kommer</a></em> (‘Your Time Will Come’) is a song by the Swedish musician Håkan Hellström, from his album <em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/Du_gamla_du_fria_(musikalbum)\">Du gamla du fria</a></em> (‘You Old You Free’).'),
(448, 104, 738, 650, 3, 'Falling: Olle Sarri.', '<em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/Ramlar\">Ramlar</a></em> (‘Falling’) is a song by the Swedish musician Håkan Hellström, from his album <em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/K%C3%A4nn_ingen_sorg_f%C3%B6r_mig_G%C3%B6teborg\">Känn ingen sorg för mig Göteborg</a></em> (‘Feel No Sadness for Me Gothenburg’).'),
(449, 104, 738, 202, 4, 'A midsummer night’s dream: Christine Meltzer.', '<em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/En_midsommarnattsdr%C3%B6m_(s%C3%A5ng)\">En midsommarnattsdröm</a></em> (‘A Midsummer Night’s Dream’) is a song by the Swedish musician Håkan Hellström, from his album <em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/Ett_kolikbarns_bek%C3%A4nnelser\">Ett kolikbarns bekännelser</a></em> (‘Confessions of a colicky baby’).'),
(450, 104, 738, 649, 5, 'A friend with a car: Jan Rippe.', '<em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/En_v%C3%A4n_med_en_bil\">En vän med en bil</a></em> (‘A Friend with a Car’) is a song by the Swedish musician Håkan Hellström, from his album <em><a target=\"_blank\" href=\"https://sv.wikipedia.org/wiki/K%C3%A4nn_ingen_sorg_f%C3%B6r_mig_G%C3%B6teborg\">Känn ingen sorg för mig Göteborg</a></em> (‘Feel No Sadness for Me Gothenburg’).'),
