--
-- Table structure for table `contestant_introductions`
--

CREATE TABLE `contestant_introductions` (
  `id` smallint(4) UNSIGNED NOT NULL COMMENT 'Unique identifier',
  `season_id` smallint(3) UNSIGNED NOT NULL COMMENT 'Season ID',
  `episode_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Episode ID',
  `contestant_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Contestant ID',
  `sort_order` tinyint(1) UNSIGNED DEFAULT NULL COMMENT 'Sort order',
  `intro_text` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Intro text',
  `intro_text_notes` varchar(1024) COLLATE utf8_unicode_ci DEFAULT NULL COMMENT 'Any relevant additional contextual or translation notes.'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

